values ('ab1289e1-1c74-5679-834f-b26ad4bdf975', 'green-curry-stir-fry', 'מוקפץ-קארי-ירוק-טבעוני-ללא-גלוטן', 'מוקפץ קארי ירוק טבעוני, ללא גלוטן', 'מנה טבעונית משביעה בסיר אחד: מוקפץ נודלס קארי ירוק עם טופו וירקות ירוקים, שמשלבת ירקות, פחמימה, חלבון ושומן לארוחת צהריים או ערב.', '2026-01-07'::date, 'ערב', array['טבעוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '0ee67b73-be88-5acf-8d39-0afc657c60d5', '/media/client/recipes/green-curry-stir-fry.jpg', 'מוקפץ קארי ירוק טבעוני, ללא גלוטן', '**מוקפץ קארי ירוק עם טופו וירקות ירוקים, מנה טבעונית וטעימה**

אני יודעת שלא כולם אוהבים קארי ושהעולם מתחלק לאנשים שאוהבים קארי ואנשים שבכלל לא אוהבים. אני בצד האוהב אם היה קשה לנחש, אבל שתדעו שלא תמיד הייתי שם וזו אהבה שנוצרה בשנתיים האחרונות, אז החלטתי להכין לראשונה קארי! מדובר על אחלה מנה משביעה לארוחת צהריים/ערב שמכילה גם ירקות, גם פחמימה, גם חלבון וגם שומן, הכל בסיר אחד.', '[{"kind":"sublabel","text":"לטופו:"},{"kind":"item","text":"חבילת טופו (300 גרם)"},{"kind":"item","text":"1 כף קורנפלור"},{"kind":"sublabel","text":"למוקפץ:"},{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"1 חבילת אטריות אורז (500 גרם)"},{"kind":"item","text":"1 ברוקולי טרי מפורק לפרחים"},{"kind":"item","text":"1 חבילת פטריות פרוסות"},{"kind":"item","text":"1 בצל חתוך לרצועות"},{"kind":"item","text":"באק צ’וי/תרד/ ירוקים שתרצו"},{"kind":"item","text":"פטריות שימאגי (לא חובה אבל מוסיף)"},{"kind":"item","text":"צרור בצל ירוק"},{"kind":"sublabel","text":"רוטב:"},{"kind":"item","text":"400 גרם קרם קוקוס (שמתי 17%)"},{"kind":"item","text":"חופן תרד"},{"kind":"item","text":"חופן בזיליקום"},{"kind":"item","text":"חופן כוסברה"},{"kind":"item","text":"2 כפות מחית קארי ירוק"},{"kind":"item","text":"2 כפות רוטב סויה דלת נתרן"},{"kind":"item","text":"1 כפית סילאן"},{"kind":"item","text":"2 שיני שום"},{"kind":"sublabel","text":"להגשה:"},{"kind":"item","text":"בצל ירוק, כוסברה, בוטנים גרוסים","split":true}]'::jsonb, '["חותכים וקוצצים מראש את כל הירקות.","חותכים את הטופו לקוביות, מעבירים לקערה ומוסיפים את הקורנפלור, מערבבים.","מחממים במחבת רחבה/ווק 2 כפות שמן זית ומוסיפים את הטופו, מטגנים 2-3 דקות.","מוסיפים את הבצל, הברוקולי, הפטריות והבאק צוי ומטגנים כ5 דקות עד ריכוך קל של הירקות.","טוחנים את כל רכיבי הרוטב במעבד מזון ושופכים את הרוטב מעל כל הירקות.","מביאים לרתיחה שהרוטב יעטוף את הירקות.","מוסיפים אטריות שבישלנו ע״פ הוראות ההכנה על גבי האריזה.","מערבבים ומבשלים כמה דקות.","מוסיפים את הבצל הירוק.","ולפני הגשה נפזר עוד בצל ירוק, כוסברה ובוטנים. בתיאבון😋"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-01-07T00:00:00Z'::timestamptz)
